import type { ComponentType, SVGProps } from "react"

/**
 * The game-mode icons: one family drawn for this app (graphic/icons_1.png and
 * icons_2.png), traced to filled paths on a 24-unit box. Plain UI glyphs - back
 * arrows, theme toggle, check marks - stay on lucide-react.
 *
 * They take the same props the Lucide icons are called with, so a mode list can
 * hold either kind. Being fills rather than strokes, `strokeWidth` means nothing
 * to them; the weight was set when they were traced.
 */
export type ModeIcon = ComponentType<{ size?: number | string; className?: string } & Omit<SVGProps<SVGSVGElement>, "ref">>

function modeIcon(name: string, d: string): ModeIcon {
    const Icon: ModeIcon = ({ size = 24, ...rest }) => (
        <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="currentColor" {...rest}>
            <path fillRule="evenodd" d={d} />
        </svg>
    )
    Icon.displayName = name
    return Icon
}

